create function pg_temp.baseline(op text,p jsonb default '{}') returns jsonb language sql as $$
 select app_private.payment_history_local_baseline_request_v2('10000000-0000-4000-8000-000000003019','20000000-0000-4000-8000-000000003019','30000000-0000-4000-8000-000000003019','60000000-0000-4000-8000-000000003019','sha256:'||repeat('b',64),'sha256:'||repeat('c',64),7,op,p)->'result';
$$;
create function pg_temp.start_payload(req uuid default '80000000-0000-4000-8000-000000003019') returns jsonb language sql as $$
 select jsonb_build_object('request_key',req,'upload_id','70000000-0000-4000-8000-000000003019','local_dataset_id',value#>>'{manifest,localDatasetId}','data_revision',value#>>'{manifest,dataRevision}','restore_epoch',value#>>'{manifest,restoreEpoch}','restore_lineage_id',value#>>'{manifest,restoreLineageId}','writer_epoch','1') from baseline_context where key='fixture';
$$;
select throws_ok($$select app_private.payment_history_local_device_actor_v2('10000000-0000-4000-8000-000000003019','20000000-0000-4000-8000-000000003019','30000000-0000-4000-8000-000000003019','60000000-0000-4000-8000-000000003019','wrong-token','sha256:'||repeat('c',64),7,'migrate')$$,'42501','payment_history_device_denied','device token hash is authenticated');
select throws_ok($$select app_private.payment_history_local_device_actor_v2('10000000-0000-4000-8000-000000003019','20000000-0000-4000-8000-000000003019','30000000-0000-4000-8000-000000003019','60000000-0000-4000-8000-000000003019','sha256:'||repeat('b',64),'sha256:'||repeat('c',64),7,null)$$,'42501','payment_history_device_denied','missing capability cannot acquire a baseline actor');
select throws_ok($$select pg_temp.baseline('start',pg_temp.start_payload()||'{"extra":true}')$$,'22023','payment_history_operation_invalid','expanded request is closed');
select throws_ok($$select public.payment_history_migration_request_v1('10000000-0000-4000-8000-000000003019','start',pg_temp.start_payload()-array['local_dataset_id','data_revision','restore_epoch','restore_lineage_id','writer_epoch'],'30000000-0000-4000-8000-000000003019','60000000-0000-4000-8000-000000003019','sha256:'||repeat('c',64),7)$$,'42501',null,'a POS session cannot impersonate a staff-web session');
insert into baseline_context select 'upload',pg_temp.baseline('upload_create',jsonb_build_object('file_name','synthetic.w7history.zip','sha256',value->>'archiveSha256','byte_length',value->>'byteLength')) from baseline_context where key='fixture';
select is((select u.actor_id from public.payment_history_uploads u join baseline_context c on u.upload_id=(c.value->>'upload_id')::uuid where c.key='upload'),'30000000-0000-4000-8000-000000003019'::uuid,'baseline upload belongs to current POS staff');
select throws_ok($$select pg_temp.baseline('start',pg_temp.start_payload()||'{"local_dataset_id":null}')$$,'22023','payment_history_local_baseline_invalid','missing dataset is rejected');
select throws_ok($$select pg_temp.baseline('start',pg_temp.start_payload()||'{"writer_epoch":"2"}')$$,'40001','payment_history_local_writer_closed','baseline is admitted against the current writer epoch');
select throws_ok($$select pg_temp.baseline('start',pg_temp.start_payload()||'{"restore_lineage_id":"invented"}')$$,'22023','payment_history_local_baseline_invalid','baseline lineage is a closed UUID');
insert into baseline_context values('start',pg_temp.baseline('start',pg_temp.start_payload()));
select is((select value->>'state' from baseline_context where key='start'),'queued','real POS actor queues the existing migration engine');
select is((select j.source_mode from public.payment_history_migration_runs j join baseline_context c on j.run_id=(c.value->>'run_id')::uuid where c.key='start'),'local_baseline_v2','source mode is server-selected');
select is((select j.actor_session_id from public.payment_history_migration_runs j join baseline_context c on j.run_id=(c.value->>'run_id')::uuid where c.key='start'),'60000000-0000-4000-8000-000000003019'::uuid,'POS actor retains its POS session identity');
select ok((select app_private.payment_history_migration_actor_current_v1(j) from public.payment_history_migration_runs j join baseline_context c on j.run_id=(c.value->>'run_id')::uuid where c.key='start'),'worker checks the current POS actor without a web login');
select throws_ok($$update public.payment_history_migration_runs set source_context=source_context||'{"restore_epoch":"1"}' where source_mode='local_baseline_v2'$$,'55000','payment_history_migration_source_immutable','an admitted source tuple is immutable');
insert into baseline_context values('lease',public.payment_history_migration_worker_v1('claim','{}')->'run');
select is((select value->>'export_version' from baseline_context where key='lease'),'history-local-export-v2','worker chooses parser version from the admitted run');
select is((select value->>'run_id' from baseline_context where key='lease'),(select value->>'run_id' from baseline_context where key='start'),'worker keeps the same scoped source run');
do $$declare f jsonb;l jsonb;begin
 select value into f from baseline_context where key='fixture';select value into l from baseline_context where key='lease';
 perform public.payment_history_migration_worker_v1('stage_objects',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'objects'));
 perform public.payment_history_migration_worker_v1('stage_movements',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'movements'));
 perform public.payment_history_migration_worker_v1('finish',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','raw_manifest',f->>'rawManifest','analysis_digest',f->>'analysisDigest'));
end;$$;
select ok((select j.state='review_ready' and j.manifest_sha256=f.value->>'manifestSha256' from public.payment_history_migration_runs j join baseline_context c on j.run_id=(c.value->>'run_id')::uuid cross join baseline_context f where c.key='start' and f.key='fixture'),'all original objects and raw CLR manifest hash are verified');
insert into baseline_context select 'review',pg_temp.baseline('review',jsonb_build_object('run_id',value->>'run_id')) from baseline_context where key='start';
select ok((select (value->>'baseline_verified')::boolean and not (value->>'freeze_verified')::boolean from baseline_context where key='review'),'local baseline is verified without inventing a frozen acknowledgement');
select ok((select (value->>'can_apply')::boolean from baseline_context where key='review'),'existing verified aliases admit the baseline automatically');
insert into baseline_context select 'apply_payload',jsonb_build_object('run_id',s.value->>'run_id','request_key','90000000-0000-4000-8000-000000003019','review_digest',v.value->>'review_digest') from baseline_context s cross join baseline_context v where s.key='start' and v.key='review';
insert into baseline_context select 'receipt',pg_temp.baseline('apply',value) from baseline_context where key='apply_payload';
select is((select value#>>'{baseline_context,state}' from baseline_context where key='receipt'),'baseline_verified','canonical baseline and local context commit together');
select is((select c.restore_lineage_id::text from public.payment_history_local_writer_contexts c where c.shop_id='10000000-0000-4000-8000-000000003019'),(select value#>>'{manifest,restoreLineageId}' from baseline_context where key='fixture'),'canonical context preserves the actual CLR restore lineage');
select ok((select writer_authority='local' and writer_epoch=1 from public.payment_history_runtime where shop_id='10000000-0000-4000-8000-000000003019'),'baseline never performs frozen-to-local or web cutover');
select is((select pg_temp.baseline('apply',value) from baseline_context where key='apply_payload'),(select value from baseline_context where key='receipt'),'lost apply response recovers the same canonical receipt');
select ok((select revision=1 from public.payment_history_runtime where shop_id='10000000-0000-4000-8000-000000003019') and (select count(*)=5 from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000003019'),'replay creates no second movement or revision');
select ok((select count(*)=5 and sum(v.gross_clp)=3380 and sum(v.net_clp)=3320 and bool_and(v.business_ticks=(o.original_object->>'business_ticks')::bigint and v.economic_digest=m.source_economic_digest and v.gross_clp=(o.original_object->>'signed_amount_clp')::bigint and v.net_clp is not distinct from (o.original_object->>'signed_net_clp')::bigint)
 from public.payment_history_local_movement_map m join public.payment_history_movement_versions v on v.shop_id=m.shop_id and v.movement_version_id=m.movement_version_id join public.payment_history_local_writer_contexts c on c.shop_id=m.shop_id and c.shop_device_id=m.shop_device_id join public.payment_history_source_objects o on o.shop_id=c.shop_id and o.source_snapshot_id=c.source_snapshot_id and o.table_name='movements' and o.local_id=m.local_movement_id where m.shop_id='10000000-0000-4000-8000-000000003019') and (select count(*)=0 from public.pos_sales where shop_id='10000000-0000-4000-8000-000000003019'),'identities, exact dates and CLP economics match the original CLR ledger without native sales');
-- A new source whose archive lineage differs from its authenticated admission
-- must fail before it can become another canonical source or context.
insert into baseline_context values('bad_start',pg_temp.baseline('start',pg_temp.start_payload('81000000-0000-4000-8000-000000003019')||'{"restore_lineage_id":"51000000-0000-4000-8000-000000003019"}'));
