do $$declare f jsonb;l jsonb;begin
 select value into f from baseline_context where key='fixture';select value into l from baseline_context where key='bad_lease';
 perform public.payment_history_migration_worker_v1('stage_objects',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'objects'));
 perform public.payment_history_migration_worker_v1('stage_movements',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'movements'));
end;$$;
select throws_ok($$select public.payment_history_migration_worker_v1('finish',jsonb_build_object('run_id',l.value->>'run_id','lease_token',l.value->>'lease_token','lease_fence',l.value->>'lease_fence','raw_manifest',f.value->>'rawManifest','analysis_digest',f.value->>'analysisDigest')) from baseline_context l cross join baseline_context f where l.key='bad_lease' and f.key='fixture'$$,'22023','payment_history_local_baseline_scope_mismatch','copied or stale source lineage cannot be admitted');
