select throws_ok($$select public.payment_history_migration_request_v1('10000000-0000-4000-8000-000000003019','status',jsonb_build_object('run_id',value->>'run_id'),'30000000-0000-4000-8000-000000003019','40000000-0000-4000-8000-000000003019','sha256:'||repeat('d',64),7) from baseline_context where key='start'$$,'42501','payment_history_job_actor_mismatch','public frozen migration cannot take over a POS baseline');
