select ok(not (select app_private.payment_history_migration_actor_current_v1(j) from public.payment_history_migration_runs j join baseline_context c on j.run_id=(c.value->>'run_id')::uuid where c.key='bad_start'),'worker observes POS revocation independently of web session');
select throws_ok($$select pg_temp.baseline('status',jsonb_build_object('run_id',value->>'run_id')) from baseline_context where key='start'$$,'42501','payment_history_device_denied','revoked POS cannot recover baseline data through web identity');
